using UnityEngine;using UnityEditor;using System;using System.Linq;using System.IO;
public static class ValidateMotorollerGauge{public static string Main(){if(!Application.isPlaying)throw new Exception("Play Mode required");GameObject copy=null,floor=null;int checks=0;void Check(bool v,string m){if(!v)throw new Exception(m);checks++;}try{var original=UnityEngine.Object.FindFirstObjectByType<MotorollerController>();copy=UnityEngine.Object.Instantiate(original.gameObject,new Vector3(10000,.02f,10000),Quaternion.identity);var motor=copy.GetComponent<MotorollerController>();var rig=motor.Movement;var gauge=copy.GetComponentInChildren<MotorollerSpeedometer>();
var left=rig.steering.GetComponentsInChildren<MeshFilter>().First(f=>f.name=="LeftMirror");var right=rig.steering.GetComponentsInChildren<MeshFilter>().First(f=>f.name=="RightMirror");Check(left.sharedMesh!=right.sharedMesh,"Mirrors have independent mesh assets");Check(left.transform.parent==rig.steering&&right.transform.parent==rig.steering,"Both mirrors follow steering");Check(left.sharedMesh.vertexCount>0&&right.sharedMesh.vertexCount>0,"Both mirrors contain geometry");Check(gauge.transform.IsChildOf(rig.steering),"Gauge follows handlebars");
floor=GameObject.CreatePrimitive(PrimitiveType.Cube);floor.transform.position=new Vector3(10000,-.5f,10000);floor.transform.localScale=new Vector3(200,1,200);Physics.SyncTransforms();rig.SetRidden(true);gauge.Refresh();Check(gauge.DisplayedKph==0&&Quaternion.Angle(gauge.Needle.localRotation,Quaternion.Euler(0,0,135))<.01f,"Stationary needle points at zero");
for(int i=0;i<180;i++)motor.Drive(1,0,false,.02f);gauge.Refresh();Check(Mathf.Abs(gauge.DisplayedKph-43.2f)<.02f,"12 m/s displays 43.2 km/h");Check(Quaternion.Angle(gauge.Needle.localRotation,Quaternion.Euler(0,0,-59.4f))<.05f,"Needle agrees with dial scale");
for(int i=0;i<100;i++)motor.Drive(0,0,true,.02f);gauge.Refresh();Check(gauge.DisplayedKph==0,"Braking returns needle to zero");
for(int i=0;i<80;i++)motor.Drive(-1,0,false,.02f);gauge.Refresh();Check(gauge.DisplayedKph>0&&Mathf.Abs(gauge.DisplayedKph-Mathf.Abs(motor.Speed)*3.6f)<.01f,"Reverse uses speed magnitude");
var leftPosition=left.transform.localPosition;var rightPosition=right.transform.localPosition;for(int i=0;i<100;i++)motor.Drive(0,1,true,.02f);Check(left.transform.localPosition==leftPosition&&right.transform.localPosition==rightPosition,"Mirror mounts stay fixed while steering");
rig.SetRidden(false);gauge.Refresh();Check(gauge.DisplayedKph==0,"Dismount resets gauge");string result="PASS: "+checks+" mirror and speedometer checks. Total triangles="+copy.GetComponentsInChildren<MeshFilter>().Sum(f=>f.sharedMesh.triangles.Length/3);File.WriteAllText("output/Motoroller/gauge-validation.txt",result);return result;
}finally{if(copy)UnityEngine.Object.DestroyImmediate(copy);if(floor)UnityEngine.Object.DestroyImmediate(floor);}}}
